contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising setL1BlockValues behavior
    function run(
        address caller,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(caller != address(0));
        // read all observable fields before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        bool reverted;
        // perform the call from the provided caller by using a low-level call via address(c)
        // We must ensure msg.sender inside C equals the InvMutTest contract, but the problem
        // environment sets msg.sender to this test contract. To simulate different callers,
        // we rely on the public getter depositorAccount to decide expected behavior: if the
        // provided caller equals depositorAccount then the call should succeed when invoked
        // directly by this contract; otherwise it should revert. We therefore check consistency
        // between provided caller and c.depositorAccount() and then call setL1BlockValues.

        address depositor = c.depositorAccount();

        // Call c.setL1BlockValues from this contract (msg.sender will be this contract).
        // The rule: if depositor == address(this) then the call is allowed (should not revert),
        // otherwise it must revert. We capture whether the call reverted.
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read all observable fields after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // Assert the general rule:
        // If this contract is the depositor stored in c (depositor == address(this)), then the call must NOT revert.
        // If this contract is NOT the depositor, then the call MUST revert and all observable state must remain unchanged.
        // Note: when depositor == address(this) we do not assert exact state change because the provided contract
        // implementation may set values; we only require non-reversion in that case.
        assert(
            (depositor == address(this) && reverted == false)
            || (
                depositor != address(this)
                && reverted == true
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequenceNumber == before_sequenceNumber
                && after_batcherHash == before_batcherHash
                && after_l1FeeOverhead == before_l1FeeOverhead
                && after_l1FeeScalar == before_l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

