        // No precondition on contract state; parameters unconstrained
        // Read depositor account and all observable state before the attempted call
        address depositor = c.depositorAccount();

        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
