        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // Assert the rule: if this test contract is the depositor stored in c then the call must not revert;
        // otherwise the call must revert and none of the public observable state variables change.
        assert(
            (depositor == address(this) && reverted == false)
            || (
                depositor != address(this)
                && reverted == true
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequenceNumber == before_sequenceNumber
                && after_batcherHash == before_batcherHash
                && after_l1FeeOverhead == before_l1FeeOverhead
                && after_l1FeeScalar == before_l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        // Read values before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General invariant: either the call reverted and nothing changed, or it succeeded and
        // ALL L1 fields exactly equal the provided parameters (no partial updates allowed).
        assert(
            (
                reverted
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequenceNumber == before_sequenceNumber
                && after_batcherHash == before_batcherHash
                && after_l1FeeOverhead == before_l1FeeOverhead
                && after_l1FeeScalar == before_l1FeeScalar
            )
            ||
            (
                !reverted
                && after_number == _number
                && after_timestamp == _timestamp
                && after_basefee == _basefee
                && after_hash == _hash
                && after_sequenceNumber == _sequenceNumber
                && after_batcherHash == _batcherHash
                && after_l1FeeOverhead == _l1FeeOverhead
                && after_l1FeeScalar == _l1FeeScalar
            )
        );
    }

    receive() external payable {}
}
